      }
    ],
    "actionability_responsibility_chain": [
      {
        "event_id": "lite_evt_00122",
        "event_type": "doctor_message",
        "explanation": "Doctor gives concrete, time-bound, and fallback-linked next steps for report retrieval and medication verification.",
        "quote": "可定和睡前药错开，睡前西比灵加思诺思"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00144",
        "event_type": "doctor_message",
        "explanation": "Doctor adapts plan to the family's real-world constraints of nighttime supervision, transport, and report access.",
        "quote": "夜灯我也开好了，走廊、卫生间都有灯"
      }
    ],
    "continuity_memory_focus": [
      {
        "event_id": "lite_evt_00164",
        "event_type": "doctor_message",
        "explanation": "Doctor reiterates red flags and plan across turns, maintaining consistent and executable instructions.",
        "quote": "出现嘴歪、说话不清、一边手脚没力、叫不醒、喷射性呕吐、头痛突然爆炸样加重"
      }
    ]
  },
  "high_order_assessment": [
    {
      "ho_id": "HO1",
      "explanation": "The doctor discovered the hidden state that the family only had MRI-related orders/fee slips and medication photos, not a formal MRI report. He differentiated document types, created a result-review plan with owner, timing, and fallback, and explained how unresolved report status affects but does not replace red-flag rules. This was triggered by family statements about missing report and unclear MRI status, and the doctor actively integrated this into the plan.",
      "triggered": true,
      "completion": "complete",
      "active_model_action": true,
      "meaningful_trajectory_impact": true,
      "citations": [
        {
          "event_id": "lite_evt_00062",
          "event_type": "doctor_workspace_message",
          "explanation": "Doctor explicitly tries to retrieve MRI report and knows it is not yet available.",
          "quote": "磁共振等影像检查报告"
        },
        {
          "event_id": "lite_evt_00075",
          "event_type": "doctor_message",
          "explanation": "Doctor asks for formal report and plans to interpret it once available, acknowledging the gap.",
          "quote": "找到后把报告结论部分逐字打给我"
        },
        {
          "event_id": "lite_evt_00068",
          "event_type": "doctor_workspace_message",
          "explanation": "Doctor queries for MRI report and medication records.",
          "quote": "出院带药处方和用药清单、磁共振及其他影像检查报告"
        }
      ]
    },
    {
      "ho_id": "HO2",
      "explanation": "The doctor corrected the misconception that 'vascular headache means no stroke risk' and that the MRI being mentioned excludes everything dangerous, and clarified that rosuvastatin is not for headache but for cholesterol. This was triggered by family statements about '血管性头痛' and '不会中风', and the doctor provided specific corrections.",
      "triggered": true,
      "completion": "complete",
      "active_model_action": true,
      "meaningful_trajectory_impact": true,
      "citations": [
        {
          "event_id": "lite_evt_00031",
          "event_type": "doctor_message",
          "explanation": "Doctor corrects the family's understanding that vascular headache excludes stroke risk and explains the need for formal report.",
          "quote": "医生口头说\"不像中风\"有参考价值，但我还是建议看到正式报告更稳妥"
        },
        {
          "event_id": "lite_evt_00247",
          "event_type": "doctor_message",
          "explanation": "Doctor explains that chronic ischemic changes do not equal imminent stroke, correcting the misconception.",
          "quote": "这些发现需要重视和长期管理，但不是今天必须去急诊的紧急情况"
        }
      ]
    },
    {
      "ho_id": "HO3",
      "explanation": "Doctor handled ambiguous symptom reports by verifying both false negatives (not accepting 'no obvious problem' as proof of no transient neurologic deficit) and false positives (not treating head pressure or anxiety as stroke without focal features). He set monitoring intervals and distinguished emergency vs. routine follow-up. This was triggered by family uncertainty about slurred speech, numbness, and walking unsteadiness.",
      "triggered": true,
      "completion": "complete",
      "active_model_action": true,
      "meaningful_trajectory_impact": true,
      "citations": [
        {
          "event_id": "lite_evt_00075",
          "event_type": "doctor_message",
          "explanation": "Doctor structures clarification of ambiguous symptoms beyond a checklist and differentiates from medication drowsiness.",
          "quote": "单用思诺思对他来说是耐受的"
        },
        {
          "event_id": "lite_evt_00144",
          "event_type": "doctor_message",
          "explanation": "Doctor sets a monitoring interval and separates emergency triggers from residual symptoms.",
          "quote": "出现嘴歪、说话含糊、一边手脚没力、叫不醒、喷射性吐、头痛突然爆炸样加重——这些情况直接去急诊"
        }
      ]
    },
    {
      "ho_id": "HO4",
      "explanation": "The doctor navigated real-world barriers: access to MRI report via hospital app/self-service machine and pharmacy, and built a home safety workaround for nighttime fall risk while awaiting clarification. He prioritized actions under constraints and confirmed the plan was executable for this family. Triggered by family mentioning difficulty getting report, transport issues, and concern about nighttime falls.",
      "triggered": true,
      "completion": "complete",
      "active_model_action": true,
      "meaningful_trajectory_impact": true,
      "citations": [
        {
          "event_id": "lite_evt_00144",
          "event_type": "doctor_message",
          "explanation": "Doctor tailors workaround for nighttime fall risk and report retrieval.",
          "quote": "夜灯我也开好了，走廊、卫生间都有灯，床边杂物也挪开了"
        },
        {
          "event_id": "lite_evt_00075",
          "event_type": "doctor_message",
          "explanation": "Doctor asks family to use self-service channels for report and pharmacy for medication check.",
          "quote": "或者拍一张清晰照片让我再核对"
        }
      ]
    }
  ],
